import { MeshBasicNodeMaterial, MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, float } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [meshUrl]
 * @property {Object} [visual]
 * @property {Object} [visual.colors]
 * @property {Array} [visual.colors.gradientStops]
 * @property {Array} [textContent]
 * @property {Object} [intent]
 * @property {Object} [intent.visualSpec]
 * @property {Array} [intent.visualSpec.textContent]
 *
 * @typedef {Object} NodeContext
 * @property {{THREE: any}} ctx
 * @property {{loadTexture: (url:string)=>Promise<any>}} textureLoader
 * @property {{loadGLB: (url:string)=>Promise<any>}} glbLoader
 * @property {{createText: (content:string, opts?:any)=>any}} fontAtlas
 * @property {{[key:string]: (target:any, params:any)=>{timeline:any, cleanup:()=>void}}} primitives
 * @property {(event:string, payload:any)=>void} emit
 * @property {string} [tier]
 */

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    PlaneGeometry,
    SphereGeometry,
    CylinderGeometry,
    Color,
    Vector3,
    Euler,
  } = ctx.THREE;

  /** root group ----------------------------------------------------------- */
  const root = new Group();
  root.name = 'orrery-node';

  /** backdrop ------------------------------------------------------------- */
  const backdropGeom = new PlaneGeometry(7, 6);
  const stops = (config.visual?.colors?.gradientStops ||
    config.colors?.gradientStops ||
    []).slice().sort((a, b) => a.at - b.at);

  let gradNode = vec3(0, 0, 0);
  let prevAt = 0;
  for (let i = 0; i < stops.length; i++) {
    const stop = stops[i];
    const col = new Color(stop.hex);
    const colVec = vec3(col.r, col.g, col.b);
    const t = smoothstep(prevAt, stop.at, uv().y);
    gradNode = mix(gradNode, colVec, t);
    prevAt = stop.at;
  }

  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = gradNode;
  backdropMat.side = 2; // DoubleSide
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -3);
  root.add(backdrop);

  /** contact shadow ------------------------------------------------------- */
  const shadowGeom = new PlaneGeometry(2.6, 1.2);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.colorNode = vec3(0, 0, 0);
  shadowMat.opacityNode = float(0.5);
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  const shadow = new Mesh(shadowGeom, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -1.2, 0);
  root.add(shadow);

  /** text --------------------------------------------------------------- */
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];
  const textGroup = new Group();

  for (const item of items) {
    const role = item.role || '';
    const fontSize = item.typography?.fontSize ?? (role === 'headline' ? 68 : 18);
    const textColor = '#e8ecf2'; // paper color per spec
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: textColor,
      align: 'center',
    });

    if (role === 'headline') {
      txt.position.set(0, -1.7, 0);
    } else {
      txt.position.set(0, -2.1, 0);
    }
    textGroup.add(txt);
  }
  root.add(textGroup);

  /** load GLB ------------------------------------------------------------ */
  const promises = [];

  promises.push(
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      /** primary gear --------------------------------------------------- */
      const primaryGear = gltf.scene.clone(true);
      const targetDiameter = 1.6;
      const scaleFactor = targetDiameter; // assumes original mesh fits unit size
      primaryGear.scale.setScalar(scaleFactor);
      primaryGear.name = 'primaryGear';
      root.add(primaryGear);

      /** secondary gear ------------------------------------------------- */
      const secondaryGear = primaryGear.clone(true);
      secondaryGear.scale.setScalar(0.9);
      secondaryGear.position.set(1.15, 0.35, -0.1);
      secondaryGear.name = 'secondaryGear';
      root.add(secondaryGear);

      /** jewel pivot ---------------------------------------------------- */
      const jewelGeom = new SphereGeometry(0.12, 32, 32);
      const jewelMat = new MeshPhysicalNodeMaterial();
      const jewelCol = new Color('#ff2a38');
      const jewelVec = vec3(jewelCol.r, jewelCol.g, jewelCol.b);
      jewelMat.colorNode = jewelVec;
      jewelMat.transmissionNode = float(0.6);
      jewelMat.iorNode = float(1.76);
      jewelMat.emissiveNode = jewelVec;
      jewelMat.emissiveIntensity = 1.8;
      const jewel = new Mesh(jewelGeom, jewelMat);
      jewel.position.set(0, 0, 0);
      root.add(jewel);

      /** shafts ---------------------------------------------------------- */
      const shaftGeom = new CylinderGeometry(0.05, 0.05, 0.8, 16);
      const shaftMat = new MeshStandardNodeMaterial();
      const inkCol = new Color('#16161d');
      shaftMat.colorNode = vec3(inkCol.r, inkCol.g, inkCol.b);
      const shaftPrimary = new Mesh(shaftGeom, shaftMat);
      shaftPrimary.rotation.x = Math.PI / 2;
      const shaftSecondary = shaftPrimary.clone();
      shaftSecondary.position.set(1.15, 0.35, -0.1);
      root.add(shaftPrimary);
      root.add(shaftSecondary);

      /** rotation animation -------------------------------------------- */
      const primarySpeed = 0.08; // rad/s
      const secondarySpeed = -0.142; // rad/s
      const primaryDur = (2 * Math.PI) / Math.abs(primarySpeed);
      const secondaryDur = (2 * Math.PI) / Math.abs(secondarySpeed);
      const rotTL = gsap.timeline({ repeat: -1 });
      rotTL.to(
        primaryGear.rotation,
        { y: '+=' + Math.PI * 2, duration: primaryDur, ease: 'none' },
        0
      );
      rotTL.to(
        secondaryGear.rotation,
        { y: '+=' + Math.PI * 2, duration: secondaryDur, ease: 'none' },
        0
      );

      /** store cleanup for rotation ------------------------------------- */
      if (!root.userData._cleanupFns) root.userData._cleanupFns = [];
      root.userData._cleanupFns.push(() => rotTL.kill());
    })
  );

  /** orbit primitive ------------------------------------------------------ */
  const orbitPrim = ctx.primitives['orbit'](root, {
    speed: 0.08,
    radius: 0.2,
  });

  /** cleanup ---------------------------------------------------------------- */
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // kill any stored GSAP timelines
    if (root.userData._cleanupFns) {
      for (const fn of root.userData._cleanupFns) fn();
    }
    // primitive cleanup
    if (orbitPrim && typeof orbitPrim.cleanup === 'function') {
      orbitPrim.cleanup();
    }
  };

  return root;
}
